    function run(address addr) public payable {
        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { initReverted = true; } else { initReverted = false; }

        bool logReverted;
        c.SetLogFile(addr); bool __rev1 = __ESBMC_reverted(); if (__rev1) { logReverted = true; } else { logReverted = false; }

        assert(!initReverted && logReverted);
