pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(address addr) internal {
        bool initReverted;
        try c.Initialized() { initReverted = false; } catch { initReverted = true; }
        bool logReverted;
        try c.SetLogFile(addr) { logReverted = false; } catch { logReverted = true; }
        assertTrue(!initReverted && logReverted);
    }

    function testFuzz_run(address addr) public {
        vm.assume(addr.code.length == 0 && uint160(addr) > 0xffff && addr != address(this) && addr != address(c) && addr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && addr != 0x000000000000000000636F6e736F6c652e6c6f67 && addr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && addr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(addr);
    }

    receive() external payable {}
}
